DROP TABLE IF EXISTS `house`;
CREATE TABLE `house`  (
  `house_id` bigint NOT NULL AUTO_INCREMENT COMMENT '房源ID',
  `landlord_id` bigint NOT NULL COMMENT '房东ID',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房源标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房源描述',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '详细地址',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省份',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '城市',
  `district` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区县',
  `longitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `rent_price` decimal(10, 2) NOT NULL COMMENT '月租金',
  `deposit_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '押金',
  `area` decimal(6, 2) NOT NULL COMMENT '面积(m²)',
  `house_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房型',
  `floor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼层',
  `orientation` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '朝向',
  `facilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配套设施',
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '图片列表(JSON)',
  `rent_option` tinyint NOT NULL DEFAULT 3 COMMENT '租赁选项：1整租 2合租 3都支持',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0待审核 1可出租 2已出租 3已下架 4审核驳回',
  `audit_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核意见',
  `view_count` int NULL DEFAULT 0 COMMENT '浏览量',
  `collect_count` int NULL DEFAULT 0 COMMENT '收藏数',
  `create_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deposit_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '押付方式：押一付一、押一付二、押一付三等',
  `property_license_front` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房产证正面图片(base64)',
  `property_license_back` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房产证背面图片(base64)',
  `property_license_other` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '其他证明材料(base64)',
  PRIMARY KEY (`house_id`) USING BTREE,
  INDEX `idx_landlord_id`(`landlord_id` ASC) USING BTREE,
  INDEX `idx_city`(`city` ASC) USING BTREE,
  INDEX `idx_rent_price`(`rent_price` ASC) USING BTREE,
  INDEX `idx_rent_option`(`rent_option` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_house_city_rent`(`city` ASC, `rent_price` ASC, `rent_option` ASC, `status` ASC) USING BTREE,
  INDEX `idx_house_landlord_status`(`landlord_id` ASC, `status` ASC, `create_time` ASC) USING BTREE,
  FULLTEXT INDEX `ft_title_desc`(`title`, `description`),
  CONSTRAINT `fk_house_landlord_id` FOREIGN KEY (`landlord_id`) REFERENCES `user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 508 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '房源表' ROW_FORMAT = Dynamic;

