-- ----------------------------
-- View structure for contract_detail_view
-- ----------------------------
DROP VIEW IF EXISTS `contract_detail_view`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `contract_detail_view` AS SELECT 
    rc.contract_id,
    rc.contract_no,
    rc.rent_start_date,
    rc.rent_end_date,
    rc.monthly_rent,
    rc.deposit_amount,
    rc.status AS contract_status,
    rc.tenant_sign_time,
    rc.landlord_sign_time,
    h.house_id,
    h.title AS house_title,
    h.address AS house_address,
    landlord.user_id AS landlord_id,
    landlord.real_name AS landlord_name,
    landlord.phone AS landlord_phone,
    tenant.user_id AS tenant_id,
    tenant.real_name AS tenant_name,
    tenant.phone AS tenant_phone
FROM `rental_contract` rc
LEFT JOIN `house` h ON rc.house_id = h.house_id
LEFT JOIN `user` landlord ON rc.landlord_id = landlord.user_id
LEFT JOIN `user` tenant ON rc.tenant_id = tenant.user_id ;

-- ----------------------------
-- View structure for house_detail_view
-- ----------------------------
DROP VIEW IF EXISTS `house_detail_view`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `house_detail_view` AS SELECT 
    h.house_id,
    h.title,
    h.description,
    h.address,
    h.province,
    h.city,
    h.district,
    h.rent_price,
    h.deposit_price,
    h.area,
    h.house_type,
    h.rent_option,
    h.status,
    h.view_count,
    h.collect_count,
    u.user_id AS landlord_id,
    u.real_name AS landlord_name,
    u.phone AS landlord_phone,
    u.avatar AS landlord_avatar,
    u.realname_status AS landlord_auth_status
FROM `house` h
LEFT JOIN `user` u ON h.landlord_id = u.user_id ;

-- ----------------------------
-- View structure for user_auth_view
-- ----------------------------
DROP VIEW IF EXISTS `user_auth_view`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `user_auth_view` AS SELECT 
    u.user_id,
    u.username,
    u.phone,
    u.email,
    u.real_name,
    u.id_card,
    u.user_type,
    u.realname_status,
    u.realname_time,
    u.realname_audit_reason,
    ra.auth_id,
    ra.auth_status AS latest_auth_status,
    ra.audit_reason AS latest_audit_reason,
    ra.create_time AS auth_apply_time
FROM `user` u
LEFT JOIN (
    SELECT 
        user_id,
        auth_id,
        auth_status,
        audit_reason,
        create_time,
        ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY create_time DESC) AS rn
    FROM `realname_auth`
) ra ON u.user_id = ra.user_id AND ra.rn = 1 ;

-- ----------------------------
-- Procedure structure for get_user_permissions
-- ----------------------------
DROP PROCEDURE IF EXISTS `get_user_permissions`;
delimiter ;;
CREATE PROCEDURE `get_user_permissions`(IN user_id_param BIGINT)
BEGIN
    SELECT DISTINCT p.*
    FROM `permission` p
    INNER JOIN `role_permission` rp ON p.perm_id = rp.perm_id
    INNER JOIN `user_role` ur ON rp.role_id = ur.role_id
    WHERE ur.user_id = user_id_param;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for get_user_roles
-- ----------------------------
DROP PROCEDURE IF EXISTS `get_user_roles`;
delimiter ;;
CREATE PROCEDURE `get_user_roles`(IN user_id_param BIGINT)
BEGIN
    SELECT r.*
    FROM `role` r
    INNER JOIN `user_role` ur ON r.role_id = ur.role_id
    WHERE ur.user_id = user_id_param;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for update_house_status
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_house_status`;
delimiter ;;
CREATE PROCEDURE `update_house_status`(IN house_id_param BIGINT,
    IN new_status TINYINT,
    IN audit_reason_param VARCHAR(500))
BEGIN
    UPDATE `house`
    SET 
        `status` = new_status,
        `audit_reason` = audit_reason_param,
        `update_time` = NOW()
    WHERE `house_id` = house_id_param;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for update_realname_status
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_realname_status`;
delimiter ;;
CREATE PROCEDURE `update_realname_status`(IN user_id_param BIGINT,
    IN new_status TINYINT,
    IN audit_reason_param VARCHAR(500),
    IN auditor_id_param BIGINT)
BEGIN
    DECLARE latest_auth_id BIGINT;
    
    -- 查找用户最新的认证记录
    SELECT auth_id INTO latest_auth_id
    FROM `realname_auth`
    WHERE user_id = user_id_param
    ORDER BY create_time DESC
    LIMIT 1;
    
    -- 更新用户表
    UPDATE `user`
    SET 
        `realname_status` = new_status,
        `realname_audit_reason` = audit_reason_param,
        `update_time` = NOW(),
        `realname_time` = IF(new_status = 1, NOW(), realname_time)
    WHERE `user_id` = user_id_param;
    
    -- 更新认证记录表
    IF latest_auth_id IS NOT NULL THEN
        UPDATE `realname_auth`
        SET 
            `auth_status` = IF(new_status = 1, 1, IF(new_status = 2, 2, auth_status)),
            `audit_reason` = audit_reason_param,
            `auditor_id` = auditor_id_param,
            `audit_time` = NOW(),
            `update_time` = NOW()
        WHERE `auth_id` = latest_auth_id;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table favorite
-- ----------------------------
DROP TRIGGER IF EXISTS `update_collect_count_insert`;
delimiter ;;
CREATE TRIGGER `update_collect_count_insert` AFTER INSERT ON `favorite` FOR EACH ROW BEGIN
    UPDATE `house`
    SET `collect_count` = `collect_count` + 1
    WHERE `house_id` = NEW.house_id;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table favorite
-- ----------------------------
DROP TRIGGER IF EXISTS `update_collect_count_delete`;
delimiter ;;
CREATE TRIGGER `update_collect_count_delete` AFTER DELETE ON `favorite` FOR EACH ROW BEGIN
    UPDATE `house`
    SET `collect_count` = `collect_count` - 1
    WHERE `house_id` = OLD.house_id;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table realname_auth
-- ----------------------------
DROP TRIGGER IF EXISTS `after_realname_auth_update`;
delimiter ;;
CREATE TRIGGER `after_realname_auth_update` AFTER UPDATE ON `realname_auth` FOR EACH ROW BEGIN
    -- 只有当认证状态从待审核(0)变为已通过(1)时
    IF OLD.auth_status = 0 AND NEW.auth_status = 1 THEN
        -- 更新用户表的实名认证状态和认证时间
        UPDATE `user`
        SET 
            `realname_status` = 1,
            `realname_time` = NEW.audit_time,
            `real_name` = NEW.real_name,
            `id_card` = NEW.id_card,
            `update_time` = NOW()
        WHERE `user_id` = NEW.user_id;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
